roleDetails['产品经理']={summary:'研究用户在具体场景中的问题，定义产品目标并推动设计、研发和运营共同验证方案。',daily:'访谈或观察用户、分析使用数据、定义问题、撰写需求、判断优先级，并跟进上线与复盘。',hard:['用户研究与问题定义','需求文档与原型','指标与实验基础','产品和技术协作流程'],soft:['倾听与追问','结构化表达','取舍与责任意识','跨团队推动'],cert:'通常没有必备证书。产品课程证书的证明力有限，真实的问题分析、原型、项目结果和复盘更重要。',education:'头部互联网和管培岗位可能看重院校与实习；其他岗位更关注行业理解、项目证据和沟通推动能力。财会专业转入需要额外补充产品方法与技术常识。',path:['理解用户、场景和问题定义','拆解一个真实产品并完成需求分析','制作低保真原型与验证方案','参与校园或实习产品项目','用数据复盘结果和个人贡献','再决定是否投入跨专业求职'],related:['解决方案顾问','ERP实施顾问','商业分析']};
function show(id){$$('.screen').forEach(x=>x.classList.remove('active'));$('#'+id).classList.add('active');scrollTo({top:0,behavior:'smooth'})}
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(t._);t._=setTimeout(()=>t.classList.remove('show'),2300)}
function bindChoices(id,key){$('#'+id).onclick=e=>{if(e.target.tagName!=='BUTTON')return;const v=e.target.dataset.value,a=state[key];if(a.includes(v)){state[key]=a.filter(x=>x!==v);e.target.classList.remove('selected')}else if(a.length<5){a.push(v);e.target.classList.add('selected')}else toast('最多选择 5 项')}}
bindChoices('interestChoices','interests');bindChoices('valueChoices','values');
