$('#interestedBtn').onclick=()=>{state.mode='guided';prepareTask();show('taskScreen')};
function prepareTask(){
  const key=state.careers[state.index],c=current(),a=assessments[key],open=openCases[key];
  const v=state.mode==='guided'?{case:c.case,questions:c.questions}:open;
  state.activeAssessment=state.mode==='guided'?a:{...open,choices:[]};
  $('#taskModeLabel').textContent=state.mode==='guided'?'案例A · 引导分析题':'案例B · 迁移挑战题';
  $('#backToCareer').textContent=state.mode==='guided'?'← 返回方向介绍':'← 返回基础案例反馈';
  $('#answerHint').textContent=state.mode==='guided'?'选择题提供脚手架，文字理由仍由你独立完成':'尝试沿用基础案例的“发现变化—解释影响—补充证据”方法';
  $('#taskTitle').textContent=`案例：${c.name}`;$('#taskCareer').textContent=c.name;$('#caseBackground').textContent=v.case;
  $('#taskBrief').innerHTML=`<h3>${state.mode==='guided'?'最后请说明你的理由':'请完成以下判断'}</h3><ol>${v.questions.map(x=>`<li>${x}</li>`).join('')}</ol>`;
  $('#guidedQuestions').innerHTML=state.mode==='guided'?a.choices.map((q,i)=>`<fieldset class="choice-question"><legend>${i+1}. ${q.q}</legend>${q.options.map((o,j)=>`<label><input type="radio" name="caseChoice${i}" value="${j}"> ${o}</label>`).join('')}</fieldset>`).join(''):'';
  $('#abilityFocus').textContent=c.focus;$('#taskAnswer').value='';$('#taskFeeling').value='';
  const supported=!!(window.SpeechRecognition||window.webkitSpeechRecognition);$('#voiceBtn').disabled=!supported;$('#voiceNote').textContent=supported?'语音识别可用。首次使用时浏览器会请求麦克风权限。':'当前浏览器不提供网页语音识别能力，请使用系统听写或键盘输入。';
}
$('#backToCareer').onclick=()=>show('careerScreen');
let recognition=null;$('#voiceBtn').onclick=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('该浏览器未提供语音识别接口，可使用系统听写');if(recognition){recognition.stop();return}recognition=new SR();recognition.lang='zh-CN';recognition.continuous=true;recognition.interimResults=true;let base=$('#taskAnswer').value;recognition.onstart=()=>{$('#voiceBtn').textContent='■ 停止语音';$('#voiceNote').textContent='正在听写。请靠近麦克风，并保持网络连接。'};recognition.onresult=e=>{let final='',temp='';for(let i=e.resultIndex;i<e.results.length;i++){const s=e.results[i][0].transcript;e.results[i].isFinal?final+=s:temp+=s}if(final){base+=(base?'\n':'')+final;$('#taskAnswer').value=base}$('#taskAnswer').placeholder=temp||'正在听写……'};recognition.onerror=e=>{const reasons={not_allowed:'未获得麦克风权限，请在浏览器设置中允许访问。','audio-capture':'没有检测到可用麦克风。',network:'语音识别服务需要网络连接，但当前连接失败。','no-speech':'没有检测到清晰语音，请靠近麦克风后重试。'};$('#voiceNote').textContent=reasons[e.error]||`语音识别失败（${e.error}），请改用键盘或系统听写。`;toast($('#voiceNote').textContent)};recognition.onend=()=>{recognition=null;$('#voiceBtn').textContent='🎙 语音输入'};recognition.start()};
function evaluateAnswer(answer,a){let keywordHits=a.keywords.filter(k=>answer.includes(k));let choiceCorrect=0,choiceTotal=state.mode==='guided'?a.choices.length:0;if(state.mode==='guided'){for(let i=0;i<a.choices.length;i++){const v=$(`input[name=caseChoice${i}]:checked`);if(!v)return{error:'请完成全部选择题'};if(Number(v.value)===a.choices[i].correct)choiceCorrect++}}const choiceScore=choiceTotal?Math.round(choiceCorrect/choiceTotal*40):30;const depth=Math.min(30,Math.round(answer.length/4));const keywordScore=Math.min(30,keywordHits.length*6);return{score:Math.min(100,choiceScore+depth+keywordScore),choiceCorrect,choiceTotal,keywordHits}}
$('#submitTask').onclick=()=>{const answer=$('#taskAnswer').value.trim(),feeling=$('#taskFeeling').value,c=current(),a=state.activeAssessment;if(answer.length<40)return toast('请回答案例问题并说明理由，至少写下40个字');if(!feeling)return toast('请选择完成任务时的真实感受');const ev=evaluateAnswer(answer,a);if(ev.error)return toast(ev.error);const positive=/很投入|有一点兴趣/.test(feeling);state.results.push({key:state.careers[state.index],name:c.name,decision:'感兴趣并体验',answer,feeling,score:ev.score,verdict:positive?'值得继续探索':'暂不优先'});$('#scoreValue').textContent=ev.score;$('#feedbackTitle').textContent=`「${c.name}」案例反馈`;$('#feedbackSummary').textContent='这个分数代表本次案例回答的完整程度，不是职业能力认证。开放案例可能存在多种合理答案。';$('#choiceResult').textContent=ev.choiceTotal?`${ev.choiceCorrect} / ${ev.choiceTotal} 题正确`:'按分析框架评估';$('#answerResult').textContent=`命中 ${ev.keywordHits.length} 个关键视角`;$('#directionVerdict').textContent=positive?'值得继续探索':'暂不优先';$('#rubricFeedback').innerHTML=`<h3>你的回答反馈</h3><ul><li>${answer.length>=100?'表达较完整，包含了足够的判断过程。':'已形成基本判断，可进一步补充原因和数据需求。'}</li><li>${ev.keywordHits.length>=3?'覆盖了多个岗位关键视角：'+ev.keywordHits.join('、'):'建议补充岗位常用视角，例如：'+a.keywords.slice(0,4).join('、')+'。'}</li><li>${ev.choiceTotal&&ev.choiceCorrect<ev.choiceTotal?'选择题存在偏差，请结合参考答案理解判断逻辑。':'基础判断方向合理，下一步重点是让依据更具体。'}</li></ul>`;$('#referenceAnswer').innerHTML=`<p>${a.reference}</p><p><b>评分说明：</b>基础判断40分、回答完整度30分、关键分析视角30分。文字关键词只用于演示版初步反馈，正式产品需由评分规则或AI结合人工复核。</p>`;$('#nextAction').textContent=c.next;$('#actionPurpose').textContent=c.purpose+' 完成这一步后，你应留下一个可比较、可复盘的成果；如果你仍不愿继续，便可以有依据地降低该方向优先级。';$('#continueBtn').textContent=state.index<state.careers.length-1?'查看下一个候选方向 →':'生成本次探索结论 →';show('feedbackScreen')};
$('#continueBtn').onclick=()=>advance();
$('#backToTask').onclick=()=>show('taskScreen');
function advance(){state.index++;if(state.index<state.careers.length){renderCareer();show('careerScreen')}else renderFinal()}
function renderFinal(){$('#summaryGrid').innerHTML=state.results.map((r,i)=>`<article class="summary-card"><span>方向 0${i+1}</span><h3>${r.name}</h3><b class="verdict">${r.verdict}</b><p>${r.decision==='暂时不感兴趣'?'了解工作内容后选择不继续，已形成一条排除证据。':`案例完成度：${r.score||'—'} 分｜感受：${r.feeling}`}</p></article>`).join('');const pos=state.results.filter(r=>r.verdict==='值得继续探索');if(pos.length){$('#finalAdvice').textContent=`优先继续了解：${pos.map(x=>x.name).join('、')}`;$('#finalWhy').textContent='这三个方向只是根据当前信息选出的第一轮样本。建议优先深化有兴趣且案例完成度较高的方向，同时到职业方向库查看相邻岗位与跨专业岗位。'}else{$('#finalAdvice').textContent='暂不锁定职业，继续扩大探索样本';$('#finalWhy').textContent='三个方向都没有形成强兴趣，不代表你没有适合的工作。请到职业方向库换一个工作类型继续体验。'}show('finalScreen')}
function saveRecord(){const records=JSON.parse(localStorage.getItem('career_mvp_records')||'[]');records.unshift({id:Date.now(),profile:state.profile,results:state.results,completedAt:new Date().toISOString()});localStorage.setItem('career_mvp_records',JSON.stringify(records.slice(0,50)));toast('结果已保存到本机测试记录')}
