$('#restartBtn').onclick=reset;$('#resetBtn').onclick=reset;
$('#backFromFinal').onclick=()=>{state.index=Math.max(0,state.careers.length-1);renderCareer();show('careerScreen')};
$('#recordsBtn').onclick=()=>{state.returnScreen=$$('.screen.active')[0]?.id||'profileScreen';renderRecords();show('recordsScreen')};$('#backFromRecords').onclick=()=>show(state.returnScreen==='recordsScreen'?'profileScreen':state.returnScreen);
