$('#exportBtn').onclick=()=>{const data=localStorage.getItem('career_mvp_records')||'[]',blob=new Blob([data],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='职业探索测试记录.json';a.click();URL.revokeObjectURL(a.href)};
function renderExplorer(filter='全部'){$('#explorerGrid').innerHTML=roleLibrary.filter(x=>filter==='全部'||x[1]===filter).map(x=>`<button class="role-card" data-role="${x[0]}"><span>${x[1]}</span><h3>${x[0]}</h3><b>${x[2]}</b><p>查看工作内容、能力、证书和准备路径 →</p></button>`).join('')}
function openRole(name){const r=roleDetails[name];if(!r)return;$('#roleCategory').textContent=roleLibrary.find(x=>x[0]===name)?.[1]||'财会职业方向';$('#roleName').textContent=name;$('#roleSummary').textContent=r.summary;$('#roleDaily').textContent=r.daily;$('#roleHard').innerHTML=r.hard.map(x=>`<li>${x}</li>`).join('');$('#roleSoft').innerHTML=r.soft.map(x=>`<li>${x}</li>`).join('');$('#roleCert').textContent=r.cert;$('#roleEducation').textContent=r.education;$('#rolePath').innerHTML=r.path.map(x=>`<li>${x}</li>`).join('');$('#relatedRoles').innerHTML=r.related.map(x=>`<button data-role="${x}">${x}</button>`).join('');show('roleDetailScreen')}
$('#exploreMoreBtn').onclick=()=>{renderExplorer();show('explorerScreen')};$('#backFromExplorer').onclick=()=>show('finalScreen');$('#backToExplorer').onclick=()=>show('explorerScreen');$('#explorerFilters').onclick=e=>{const b=e.target.closest('button');if(!b)return;$$('#explorerFilters button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');renderExplorer(b.dataset.filter)};$('#explorerGrid').onclick=e=>{const b=e.target.closest('[data-role]');if(b)openRole(b.dataset.role)};$('#relatedRoles').onclick=e=>{const b=e.target.closest('[data-role]');if(b&&roleDetails[b.dataset.role])openRole(b.dataset.role)};
if(document.modelContext?.registerTool)try{document.modelContext.registerTool({name:'start_career_exploration',title:'开始职业探索',description:'根据学生基本情况开始逐个验证三个职业方向。',inputSchema:{type:'object',properties:{grade:{type:'string'},major:{type:'string'},interests:{type:'array',items:{type:'string'}},values:{type:'array',items:{type:'string'}},clarity:{type:'string'}},required:['grade','major','interests','values','clarity'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){state.profile=input;state.interests=input.interests;state.values=input.values;state.careers=choose(input.major,input.interests);state.index=0;state.results=[];renderCareer();show('careerScreen');return{firstDirection:current().name,total:3}}})}catch(e){}

/* V0.6: real portrait recalibration, progressive cases and deeper role guidance */
const portraitDimensions=[['行动验证','研究理解'],['沟通推动','独立深思'],['逻辑证据','体验关怀'],['结构计划','灵活探索']];
function preferenceState(scores,pair){const gap=(scores[pair[0]]||0)-(scores[pair[1]]||0);return{label:Math.abs(gap)<=1?`${pair[0]} / ${pair[1]}（情境型）`:gap>0?pair[0]:pair[1],winner:gap>=0?pair[0]:pair[1],gap}}
function paintPortrait(calibrated=false){const states=portraitDimensions.map(d=>preferenceState(state.profile.scores,d));state.profile.preferences=states.map(x=>x.label);const strong=states.filter(x=>Math.abs(x.gap)>=2).map(x=>x.winner),situational=states.filter(x=>Math.abs(x.gap)<=1).map(x=>x.label.split('（')[0]);$('#portraitTitle').textContent=`${state.profile.major} · ${strong.slice(0,2).join(' × ')||'多情境适应型'}`;$('#portraitIntro').textContent=`${calibrated?'补充回答已参与重新计分。':'根据12道情境题，'}你有${strong.length?strong.join('、'):'多项均衡倾向'}；${situational.length?`在${situational.join('、')}之间会随场景变化。`:'当前倾向较明确。'}这不是能力定论，后续还要用案例验证。`;$('#portraitTags').innerHTML=states.map(x=>`<span>${x.label}</span>`).join('');$('#portraitStrengths').textContent=strong.includes('逻辑证据')?'更容易从事实、标准和数据中形成判断。':strong.includes('体验关怀')?'更容易察觉人的感受、需求和协作影响。':'能够根据任务在人与证据之间切换，但需要用实际案例确认稳定优势。';$('#portraitEnergy').textContent=strong.includes('沟通推动')?'协作、表达并推动结果发生的任务。':strong.includes('独立深思')?'可以独立研究并形成完整观点的任务。':'既需要独立思考、又允许适度交流的任务。';$('#portraitCaution').textContent=situational.length?`你的${situational.join('、')}倾向接近，推荐方向时不会据此做强判断，将重点观察真实任务表现。`:(strong.includes('结构计划')?'继续验证面对变化时的调整能力。':'继续验证长期任务中的节奏与收尾能力。');$('#portraitValues').textContent=state.values.join('、')}
buildPortrait=function(){const answers=preferenceItems.map((_,i)=>$(`input[name=pref${i+1}]:checked`)?.value);if(answers.some(x=>!x))return toast('请完成全部12道情境题');const scores={};answers.forEach(x=>scores[x]=(scores[x]||0)+1);state.profile={grade:$('#grade').value,major:$('#major').value.trim(),interests:[...state.interests],values:[...state.values],clarity:$('input[name=clarity]:checked').value,scores,baseScores:{...scores},startedAt:new Date().toISOString()};state.careers=choose(state.profile.major,state.interests);state.index=0;state.results=[];paintPortrait(false);show('portraitScreen')};
$('#buildPortrait').onclick=buildPortrait;
$('#rebuildPortrait').onclick=()=>{const extra=[1,2,3,4].map(i=>$(`input[name=clarify${i}]:checked`)?.value);if(extra.some(x=>!x))return toast('请完成四道补充问题');const scores={...state.profile.baseScores};const add=k=>scores[k]=(scores[k]||0)+1;extra[0]==='分析与研究'?add('研究理解'):add('沟通推动');extra[1]==='逻辑与细节'?add('逻辑证据'):add('体验关怀');extra[2]==='排斥重复'?add('灵活探索'):add('结构计划');if(extra[3]==='解决难题'){add('研究理解');add('逻辑证据')}else{add('沟通推动');add('行动验证')}state.profile.scores=scores;state.profile.clarifications=extra;paintPortrait(true);show('portraitScreen')};

// Interested students always start with the supported foundation case.
$('#interestedBtn').onclick=()=>{state.mode='guided';prepareTask();show('taskScreen')};
$('#backToCareer').onclick=()=>state.mode==='open'?show('feedbackScreen'):show('careerScreen');

function updateAttempt(result,attempt){const old=state.results.find(x=>x.key===result.key);if(old){old.attempts=old.attempts||[];old.attempts=old.attempts.filter(x=>x.mode!==attempt.mode);old.attempts.push(attempt);Object.assign(old,result)}else setResult({...result,attempts:[attempt]})}
function renderCaseFeedback(ev,answer,feeling,a){const c=current(),positive=/很投入|有一点兴趣/.test(feeling),stage=state.mode==='guided'?'基础案例':'迁移案例';updateAttempt({key:state.careers[state.index],name:c.name,decision:'感兴趣并体验',answer,feeling,score:ev.score,verdict:positive?'值得继续探索':'暂不优先'},{mode:state.mode,score:ev.score,feeling,answer});$('#scoreValue').textContent=ev.score;$('#feedbackStage').textContent=`${stage}反馈`;$('#feedbackTitle').textContent=`「${c.name}」${stage}`;$('#feedbackSummary').textContent=state.mode==='guided'?'你已经完成一次带引导的岗位判断。下面可以查看方法，再决定是否用它解决一个不同背景的问题。':'这次重点不是重复知识点，而是观察你能否把第一题的方法迁移到新业务背景。';$('#choiceResult').textContent=ev.choiceTotal?`${ev.choiceCorrect} / ${ev.choiceTotal} 题正确`:'完成迁移判断';$('#answerResult').textContent=`覆盖 ${ev.keywordHits.length} 个关键视角`;$('#directionVerdict').textContent=positive?'愿意继续了解':'当前兴趣偏低';$('#rubricFeedback').innerHTML=`<h3>你的回答反馈</h3><ul><li>${answer.length>=100?'判断过程较完整，能看到你的分析路径。':'已经形成判断，若补充数据依据和因果关系会更扎实。'}</li><li>${ev.keywordHits.length>=3?'你覆盖了多个岗位视角：'+ev.keywordHits.join('、'):'可对照参考答案补充：'+a.keywords.slice(0,4).join('、')+'。'}</li><li>${state.mode==='open'?'这道题用于检验方法迁移，不要求答案与示例逐字一致。':ev.choiceTotal&&ev.choiceCorrect<ev.choiceTotal?'先理解选择题偏差，再决定是否挑战迁移案例。':'基础判断正确，可以尝试把方法带到新背景。'}</li></ul>`;$('#referenceAnswer').innerHTML=`<p>${a.reference}</p><p><b>评分边界：</b>分数反映本次回答的完整程度，不是职业能力认证。开放回答允许多种合理方案。</p>`;if(state.mode==='guided'){$('#nextAction').textContent='是否用刚学到的方法挑战一个新背景？';$('#actionPurpose').textContent='第二题会更换行业和数据背景，但继续观察同一项核心能力。它用于验证你是否真正理解方法、能否举一反三，而不是把第一题再做一遍。';$('#feedbackChoice').innerHTML='<button class="primary-btn" data-next="transfer">现在继续挑战迁移案例 →</button><button class="outline-btn" data-next="stop">暂时不想继续</button>';$('#continueBtn').hidden=true}else{const r=state.results.find(x=>x.key===state.careers[state.index]),base=r?.attempts?.find(x=>x.mode==='guided');$('#nextAction').textContent='两次案例已形成一组可比较证据';$('#actionPurpose').textContent=`基础案例 ${base?.score??'—'} 分，迁移案例 ${ev.score} 分。${ev.score>=(base?.score||0)?'你在更少引导下保持或提升了完成度，说明方法具有一定迁移性。':'迁移到新背景后完成度下降，建议先理解参考答案，不必据此否定这个方向。'}`;$('#feedbackChoice').innerHTML='';$('#continueBtn').hidden=false;$('#continueBtn').textContent=state.index<state.careers.length-1?'查看下一个候选方向 →':'生成本次探索结论 →'}show('feedbackScreen')}
$('#submitTask').onclick=()=>{const answer=$('#taskAnswer').value.trim(),feeling=$('#taskFeeling').value,a=state.activeAssessment;if(answer.length<40)return toast('请回答案例问题并说明理由，至少写下40个字');if(!feeling)return toast('请选择完成任务时的真实感受');const ev=evaluateAnswer(answer,a);if(ev.error)return toast(ev.error);renderCaseFeedback(ev,answer,feeling,a)};
$('#feedbackChoice').onclick=e=>{const b=e.target.closest('[data-next]');if(!b)return;if(b.dataset.next==='transfer'){state.mode='open';prepareTask();show('taskScreen');return}$('#nextAction').textContent='请选择暂时停止的主要原因';$('#actionPurpose').textContent='原因会帮助区分“对职业没兴趣”和“题目太难或体验方式不合适”，避免一次体验就误判职业。';$('#feedbackChoice').innerHTML='<div class="stop-reasons"><button data-reason="内容不感兴趣">内容不感兴趣</button><button data-reason="题目太难">题目太难</button><button data-reason="题目太简单">题目太简单</button><button data-reason="不喜欢这种体验形式">不喜欢这种体验形式</button><button data-reason="现在没有精力">现在没有精力</button></div>'};
$('#feedbackChoice').addEventListener('click',e=>{const b=e.target.closest('[data-reason]');if(!b)return;const r=state.results.find(x=>x.key===state.careers[state.index]);if(r){r.stopReason=b.dataset.reason;if(b.dataset.reason==='内容不感兴趣')r.verdict='暂不优先'}advance()});

const capabilityDetails={
'核算会计':{hard:[['会计准则与三张报表','理解常见确认、计量与列报规则，知道资产负债表、利润表和现金流量表如何勾稽。例如能解释“有利润但现金不足”的可能原因。'],['账务处理与月末结账','能从原始单据判断科目、制作凭证、核对明细与总账，并按清单完成结账。'],['Excel与财务系统','能使用查找、条件汇总、数据透视表核对数据，并理解ERP中采购到付款、销售到收款的基本链路。']],soft:[['严谨与责任感','金额、期间和科目出现异常时主动复核，不用“差不多”代替证据。'],['业务沟通','能向非财务同事解释缺少什么单据、为什么需要以及如何补齐。']]},
'财务分析':{hard:[['财务报表与经营指标','能拆解收入、成本、利润和现金流，理解指标变化来自销量、价格、结构还是效率。'],['Excel建模与数据处理','能用函数、透视表和图表完成预算实际对比，并保留可复核的数据链路。'],['分析框架','能提出异常、形成假设、补充证据，再给出有边界的经营建议。']],soft:[['业务追问','不止报告数字变化，还会追问业务动作、客户和流程原因。'],['结论表达','先说结论与影响，再展示关键证据，并明确不确定性。']]},
'审计':{hard:[['会计与审计程序','理解主要科目风险，并能选择检查、函证、盘点或分析性复核等程序。'],['审计底稿','能记录目的、样本、证据、结论与复核痕迹，让别人可以重现判断。']],soft:[['职业怀疑','对异常保持追问，但不预设对方有错。'],['高压协作','在截止日期内管理多份材料，及时暴露阻塞而不是最后才反馈。']]},
'税务':{hard:[['主要税种与申报','理解增值税、企业所得税等基本计税逻辑，能核对申报数据与账务。'],['政策检索','能找到有效政策原文，识别适用主体、时间和例外条件。']],soft:[['合规判断','区分可筹划、需核实和不可触碰的事项。'],['持续学习','政策变化后能更新流程并用清楚语言提醒业务。']]},
'资金管理':{hard:[['现金流与资金计划','能根据收付款节奏预测资金缺口并设置安全余额。'],['银行结算与融资基础','理解账户、票据、授信和常见融资资料。']],soft:[['风险意识','优先保障资金安全、授权和时效。'],['协调能力','在业务需求、银行规则和财务制度之间推进解决。']]},
'内控与风险':{hard:[['流程与风险矩阵','能画出关键流程，识别错误、舞弊和合规风险，并对应控制措施。'],['控制测试','能选择样本、检查证据并区分设计缺陷与执行缺陷。']],soft:[['系统思考','看到单点问题背后的流程和责任边界。'],['推动整改','能把风险翻译成业务影响，并跟进责任人与期限。']]},
'财务BP':{hard:[['预算预测与经营分析','能把业务计划转成财务预测，并滚动更新关键假设。'],['业务指标体系','理解收入漏斗、客户、产品和效率指标如何影响利润。']],soft:[['影响决策','不用财务术语压人，而是提供可选择的方案与后果。'],['商业敏感度','能发现数字背后的业务机会与风险。']]},
'ERP实施顾问':{hard:[['财务业务流程','能说明采购、销售、库存和财务之间的数据流与控制点。'],['需求、配置与测试','能把用户需求写成可测试规则，准备数据并记录缺陷。']],soft:[['问题定位','先复现并缩小范围，再判断是数据、配置、权限还是流程问题。'],['客户沟通','面对模糊诉求时确认目标、边界和验收标准。']]},
'商业分析':{hard:[['指标与问题拆解','能把经营问题拆成可计算指标和验证假设。'],['数据分析与呈现','能用Excel/SQL处理数据，用图表说明变化、原因与局限。']],soft:[['结构化思考','把复杂问题拆清优先级和因果链。'],['利益相关方沟通','理解不同部门目标并推动形成共同判断。']]},
'数据分析':{hard:[['SQL与数据清洗','能筛选、关联、分组和检查缺失重复数据，保证口径可复现。'],['统计与可视化','理解描述统计、对照和相关不等于因果，能选择合适图表。']],soft:[['问题定义','先明确业务决策，再决定分析哪些数据。'],['证据边界','主动说明数据限制，不把猜测包装成结论。']]},
'解决方案顾问':{hard:[['需求与方案设计','能梳理客户现状、痛点和约束，把产品能力映射成可落地方案。'],['演示与验证','能设计演示脚本、试点范围和验收标准。']],soft:[['倾听与提问','从客户表述中分辨真正目标和表面需求。'],['跨团队推动','协调销售、产品和交付团队，管理承诺边界。']]},
'企业运营':{hard:[['目标与流程拆解','能把目标拆成指标、动作、负责人和时间节点。'],['数据复盘','能比较计划与结果，定位流程瓶颈并提出下一轮实验。']],soft:[['执行与应变','在变化中抓住关键路径，及时调整资源。'],['协作推动','让多人知道各自交付物和依赖关系。']]},
'产品经理':{hard:[['用户研究与问题定义','能区分用户的表面抱怨与真实场景问题，并用访谈、观察或数据验证，而不是只凭个人感受。'],['需求与原型','能写清目标用户、使用场景、功能规则和验收标准，并用低保真原型帮助团队对齐。'],['指标与验证','能为功能设定成功指标，通过小范围测试判断方案是否真正解决问题。']],soft:[['取舍与责任意识','面对时间、技术和业务约束时能说明优先级，并对暂时不做什么负责。'],['跨团队推动','能理解设计、研发和运营的不同关注点，把分歧转化成可执行决定。']]}
};
const pathOverrides={
'核算会计':['学好会计基础与Excel','完成一套账务处理模拟','体验财务软件或ERP流程','根据目标决定是否考初级会计','寻找企业财务或事务所实习','用真实经历确认细分方向'],
'财务分析':['理解三张报表与管理会计','掌握Excel分析方法','完成预算差异或经营分析案例','补充SQL或可视化工具','寻找财务分析/经营分析实习','整理作品并复盘能力差距'],
'审计':['建立会计与审计基础','完成底稿、抽样和盘点模拟','体验事务所真实工作节奏','根据长期目标规划CPA','寻找审计或内控实习','用项目证据准备校招'],
'ERP实施顾问':['理解财务与业务流程','体验ERP沙盘或系统课程','完成需求与测试模拟项目','选择一个系统模块深入学习','寻找实施或数字化项目实践','用项目结果验证客户服务意愿']};
function detailSkills(name,type,fallback){const rows=capabilityDetails[name]?.[type];return(rows||fallback.map(x=>[x,`理解这项能力在${name}日常工作中的用途，并能通过案例或项目展示，而不只停留在课程名称。`])).map(x=>`<section><h4>${x[0]}</h4><p>${x[1]}</p></section>`).join('')}
function jdSamples(name,r){const key=(capabilityDetails[name]?.hard||[])[0]?.[0]||r.hard[0];return[{size:'小型企业',title:`${name}助理 / 专员`,text:`协助完成日常业务，熟练使用Excel，能够独立跟进基础事项并保证数据准确。`,signal:'更看重能否尽快上手，职责通常较宽。'},{size:'中型企业',title:`${name}专员`,text:`负责固定模块，按流程输出结果，发现异常并与相关部门沟通，具备${key}基础。`,signal:'更强调流程、协作和稳定交付。'},{size:'大型企业',title:`${name}管培 / 分析岗位`,text:`支持复杂业务或项目，能够形成分析结论并清晰汇报；相关实习、系统工具和项目成果优先。`,signal:'分工更细，通常增加学历、实习或平台要求。'}]}
openRole=function(name){const r=roleDetails[name];if(!r)return;$('#roleCategory').textContent=roleLibrary.find(x=>x[0]===name)?.[1]||'财会职业方向';$('#roleName').textContent=name;$('#roleSummary').textContent=r.summary;$('#roleDaily').textContent=r.daily;$('#roleHard').innerHTML=detailSkills(name,'hard',r.hard);$('#roleSoft').innerHTML=detailSkills(name,'soft',r.soft);$('#roleCert').textContent=r.cert;$('#roleEducation').textContent=r.education;const path=pathOverrides[name]||r.path.map(x=>x.replace(/^大[一二三四]：/,'')).slice(0,5);$('#rolePath').innerHTML=path.map((x,i)=>`<div class="path-step"><b>${String(i+1).padStart(2,'0')}</b><span>${x}</span></div>`).join('');const jds=jdSamples(name,r);$('#roleJds').innerHTML=jds.map(x=>`<section><small>${x.size}</small><h4>${x.title}</h4><p>${x.text}</p><em>${x.signal}</em></section>`).join('');$('#roleJdCommon').innerHTML=`<b>三类岗位的共同点</b><p>都在反复验证三件事：相关专业基础、工具与流程能力、把结果准确交付并与他人协作。企业规模越大，通常越重视细分经验、实习证据和表达能力。</p>`;$('#relatedRoles').innerHTML=r.related.map(x=>`<button data-role="${x}">${x}</button>`).join('');show('roleDetailScreen')};

/* V0.8 independent calendar and local todo planner */
const TODO_KEY='career_mvp_todos';
let calendarCursor=new Date(),selectedCalendarDate=formatDate(new Date());
function formatDate(d){return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function parseLocalDate(s){const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)}
function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function getTodos(){try{return JSON.parse(localStorage.getItem(TODO_KEY)||'[]')}catch{return[]}}
function saveTodos(items){localStorage.setItem(TODO_KEY,JSON.stringify(items))}
function openHome(){show('homeScreen')}
function openCareer(){show('profileScreen')}
function openCalendar(date=selectedCalendarDate){selectedCalendarDate=date;calendarCursor=parseLocalDate(date);renderCalendar();show('calendarScreen')}
$('#homeBtn').onclick=e=>{e.preventDefault();openHome()};$('#profileToHome').onclick=openHome;$('#calendarToHome').onclick=openHome;$('#startCareerBtn').onclick=openCareer;$('#startCalendarBtn').onclick=()=>openCalendar();$('#careerNavBtn').onclick=openCareer;$('#calendarNavBtn').onclick=()=>openCalendar();
function renderCalendar(){const y=calendarCursor.getFullYear(),m=calendarCursor.getMonth(),today=formatDate(new Date()),items=getTodos();$('#calendarMonth').textContent=`${y}年 ${m+1}月`;const first=new Date(y,m,1),offset=(first.getDay()+6)%7,last=new Date(y,m+1,0).getDate(),prevLast=new Date(y,m,0).getDate();let cells=[];for(let i=0;i<42;i++){let d,muted=false;if(i<offset){d=new Date(y,m-1,prevLast-offset+i+1);muted=true}else if(i>=offset+last){d=new Date(y,m+1,i-offset-last+1);muted=true}else d=new Date(y,m,i-offset+1);const key=formatDate(d),dayItems=items.filter(x=>x.date===key&&!x.done);cells.push(`<button class="calendar-day ${muted?'muted':''} ${key===today?'today':''} ${key===selectedCalendarDate?'selected':''}" data-date="${key}"><span>${d.getDate()}</span>${dayItems.slice(0,2).map(x=>`<i class="priority-${x.priority}">${escapeHtml(x.time)} ${escapeHtml(x.title)}</i>`).join('')}${dayItems.length>2?`<small>还有 ${dayItems.length-2} 项</small>`:''}</button>`)}$('#calendarGrid').innerHTML=cells.join('');renderAgenda()}
function renderAgenda(){const d=parseLocalDate(selectedCalendarDate),items=getTodos().filter(x=>x.date===selectedCalendarDate).sort((a,b)=>a.time.localeCompare(b.time));$('#agendaDate').textContent=`${d.getMonth()+1}月${d.getDate()}日 · ${'日一二三四五六'[d.getDay()]}`;$('#agendaList').innerHTML=items.length?items.map(x=>`<article class="agenda-item ${x.done?'done':''}"><button class="todo-check" data-check="${x.id}" aria-label="${x.done?'标记未完成':'标记完成'}">${x.done?'✓':''}</button><div><div class="agenda-meta"><span>${escapeHtml(x.time)}</span><span>${escapeHtml(x.category)}</span><b class="priority-${x.priority}">${escapeHtml(x.priority)}</b></div><h4>${escapeHtml(x.title)}</h4>${x.notes?`<p>${escapeHtml(x.notes)}</p>`:''}${x.reminder?'<small>提醒已开启</small>':''}</div><button class="todo-delete" data-delete="${x.id}" aria-label="删除待办">删除</button></article>`).join(''):'<div class="agenda-empty"><b>这一天还没有安排</b><p>新建待办后，它会自动出现在这里。</p></div>'}
function showTodoForm(){const date=$('#todoDate');date.value=selectedCalendarDate;$('#todoTime').value=$('#todoTime').value||'09:00';$('#todoSheet').hidden=false;setTimeout(()=>$('#todoTitle').focus(),30)}
function hideTodoForm(){$('#todoSheet').hidden=true;$('#todoForm').reset()}
$('#openTodoFormBtn').onclick=showTodoForm;$('#agendaAddBtn').onclick=showTodoForm;$('#closeTodoForm').onclick=hideTodoForm;$('#todoSheet').onclick=e=>{if(e.target===$('#todoSheet'))hideTodoForm()};
$('#calendarGrid').onclick=e=>{const b=e.target.closest('[data-date]');if(!b)return;selectedCalendarDate=b.dataset.date;const d=parseLocalDate(selectedCalendarDate);calendarCursor=new Date(d.getFullYear(),d.getMonth(),1);renderCalendar()};$('#prevMonth').onclick=()=>{calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()-1,1);renderCalendar()};$('#nextMonth').onclick=()=>{calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+1,1);renderCalendar()};
$('#todoForm').onsubmit=e=>{e.preventDefault();const title=$('#todoTitle').value.trim(),date=$('#todoDate').value,time=$('#todoTime').value;if(!title||!date||!time)return toast('请填写事项、日期和时间');const items=getTodos();items.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,6),title,date,time,category:$('#todoCategory').value,priority:$('#todoPriority').value,notes:$('#todoNotes').value.trim(),reminder:$('#todoReminder').checked,done:false,notified:false,createdAt:new Date().toISOString()});saveTodos(items);selectedCalendarDate=date;calendarCursor=parseLocalDate(date);hideTodoForm();renderCalendar();toast('待办已添加到日历');if($('#todoReminder').checked&&Notification.permission!=='granted')toast('待办已保存；点击“开启提醒”允许浏览器通知')};
$('#agendaList').onclick=e=>{const check=e.target.closest('[data-check]'),del=e.target.closest('[data-delete]'),items=getTodos();if(check){const item=items.find(x=>x.id===check.dataset.check);if(item){item.done=!item.done;saveTodos(items);renderCalendar()}return}if(del&&confirm('确定删除这条待办吗？')){saveTodos(items.filter(x=>x.id!==del.dataset.delete));renderCalendar();toast('待办已删除')}};
$('#enableNotifyBtn').onclick=async()=>{if(!('Notification'in window))return toast('当前浏览器不支持系统通知');if(Notification.permission==='granted')return toast('提醒已经开启');const p=await Notification.requestPermission();toast(p==='granted'?'提醒已开启，到点时请保持网页可运行':'没有获得通知权限，可在浏览器设置中重新开启')};
function checkTodoReminders(){const now=new Date(),items=getTodos();let changed=false;items.forEach(x=>{if(!x.reminder||x.done||x.notified)return;const due=new Date(`${x.date}T${x.time}:00`);if(due<=now){x.notified=true;changed=true;const body=`${x.time} · ${x.title}`;if('Notification'in window&&Notification.permission==='granted')new Notification('起点待办提醒',{body,icon:'favicon.svg'});toast(`待办提醒：${x.title}`)}});if(changed)saveTodos(items)}
setInterval(checkTodoReminders,30000);setTimeout(checkTodoReminders,1000);

/* V0.9 growth archive, weekly review, gentle nudges and capability check */
const ARCHIVE_KEY='career_mvp_growth_archive',DIRECTION_KEY='career_mvp_direction_log',REFLECTION_KEY='career_mvp_weekly_reflections',CAP_KEY='career_mvp_capabilities',TARGET_KEY='career_mvp_target_role';
function readStore(k,f){try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(f))}catch{return f}}
function writeStore(k,v){localStorage.setItem(k,JSON.stringify(v))}
function weekStart(d=new Date()){const x=new Date(d);x.setHours(0,0,0,0);const day=(x.getDay()+6)%7;x.setDate(x.getDate()-day);return x}
function weekKey(){return formatDate(weekStart())}
function weekItems(){const s=weekStart(),e=new Date(s);e.setDate(e.getDate()+6);return getTodos().filter(x=>{const d=parseLocalDate(x.date);return d>=s&&d<=e})}
function ensureArchive(){if($('#archiveScreen'))return;const roles=roleLibrary.map(x=>x[0]);const sec=document.createElement('section');sec.className='screen';sec.id='archiveScreen';sec.innerHTML=`<button class="back-btn" id="archiveToHome">← 返回功能首页</button><div class="archive-head"><div><p class="eyebrow">成长档案</p><h2>把走过的路，变成下一步。</h2><p>记录技能、项目、比赛、证书、实习与方向变化，给自己一份可回看的证据。</p></div><div class="archive-actions"><button class="outline-btn" id="archiveQuickReviewBtn">本周复盘</button><button class="primary-btn" id="archiveAddBtn">＋ 记录一项成长</button></div></div><div class="archive-grid"><article class="archive-summary" id="archiveSummary"></article><article class="archive-focus"><label>当前目标岗位<select id="targetRoleSelect">${roles.map(r=>`<option>${escapeHtml(r)}</option>`).join('')}</select></label><div id="targetRoleIntro"></div></article></div><div class="archive-panels"><article class="archive-panel"><div class="panel-title"><h3>本周回顾</h3><span id="weekRange"></span></div><div id="weeklySummary"></div><textarea id="weeklyReflection" placeholder="这周我学到了什么？下周最小的一步是什么？"></textarea><button class="primary-btn" id="saveReflectionBtn">保存本周复盘</button></article><article class="archive-panel"><div class="panel-title"><h3>目标岗位能力对照</h3><span id="capabilityProgress"></span></div><p id="capabilityIntro"></p><div id="capabilityList"></div></article><article class="archive-panel"><div class="panel-title"><h3>方向变化</h3><button class="outline-btn" id="directionChangeBtn">记录变化</button></div><div id="directionLogList"></div></article></div><article class="archive-panel archive-records"><div class="panel-title"><h3>成长记录</h3><span>最近记录</span></div><div id="archiveRecordList"></div></article><div class="archive-sheet" id="archiveSheet" hidden><form id="archiveForm" class="sheet-card"><button type="button" class="sheet-close" id="closeArchive">×</button><h3>记录一项成长</h3><label>类型<select id="archiveCategory"><option>技能</option><option>项目</option><option>比赛</option><option>证书</option><option>实习</option><option>职业规划</option></select></label><label>名称<input id="archiveTitle" required placeholder="例如：完成一份财务分析案例"></label><label>日期<input id="archiveDate" type="date" required></label><label>补充说明<textarea id="archiveDetail" placeholder="写下成果、链接或你的收获"></textarea></label><button class="primary-btn">保存记录</button></form></div><div class="archive-sheet" id="directionSheet" hidden><form id="directionForm" class="sheet-card"><button type="button" class="sheet-close" id="closeDirection">×</button><h3>记录方向变化</h3><label>职业方向<select id="directionRole">${roles.map(r=>`<option>${escapeHtml(r)}</option>`).join('')}</select></label><label>变化<select id="directionDecision"><option>加入关注</option><option>暂不考虑</option><option>排除方向</option></select></label><label>原因<textarea id="directionReason" required placeholder="是什么经历让你这样决定？"></textarea></label><button class="primary-btn">保存变化</button></form></div>`;document.querySelector('main').appendChild(sec);const nav=document.createElement('button');nav.className='text-btn';nav.id='archiveNavBtn';nav.textContent='成长档案';document.querySelector('.topbar').insertBefore(nav,$('#recordsBtn'));const card=document.createElement('button');card.className='hub-card archive-hub';card.id='startArchiveBtn';card.innerHTML='<span class="hub-number">03</span><div><small>成长证据</small><h2>成长档案</h2><p>记录技能、项目、比赛、证书、实习与方向变化。</p><b>打开成长档案 →</b></div>';$('.hub-grid').appendChild(card);$('#archiveToHome').onclick=openHome;$('#archiveNavBtn').onclick=openArchive;$('#startArchiveBtn').onclick=openArchive;$('#archiveAddBtn').onclick=()=>{$('#archiveSheet').hidden=false;$('#archiveDate').value=formatDate(new Date())};$('#closeArchive').onclick=()=>$('#archiveSheet').hidden=true;$('#directionChangeBtn').onclick=()=>$('#directionSheet').hidden=false;$('#closeDirection').onclick=()=>$('#directionSheet').hidden=true;$('#archiveQuickReviewBtn').onclick=()=>$('#weeklyReflection').focus();$('#targetRoleSelect').onchange=renderArchive;$('#saveReflectionBtn').onclick=()=>{const r=readStore(REFLECTION_KEY,{});r[weekKey()]=$('#weeklyReflection').value.trim();writeStore(REFLECTION_KEY,r);toast('本周复盘已保存')};$('#archiveForm').onsubmit=e=>{e.preventDefault();const a=readStore(ARCHIVE_KEY,[]);a.unshift({id:Date.now(),category:$('#archiveCategory').value,title:$('#archiveTitle').value.trim(),date:$('#archiveDate').value,detail:$('#archiveDetail').value.trim()});writeStore(ARCHIVE_KEY,a);e.target.reset();$('#archiveSheet').hidden=true;renderArchive();toast('成长记录已保存')};$('#directionForm').onsubmit=e=>{e.preventDefault();const a=readStore(DIRECTION_KEY,[]);a.unshift({id:Date.now(),role:$('#directionRole').value,decision:$('#directionDecision').value,reason:$('#directionReason').value.trim(),date:formatDate(new Date())});writeStore(DIRECTION_KEY,a);e.target.reset();$('#directionSheet').hidden=true;renderArchive();toast('方向变化已记录')};$('#capabilityList').onclick=e=>{const b=e.target.closest('[data-cap]');if(!b)return;const role=$('#targetRoleSelect').value,c=readStore(CAP_KEY,{});c[role]=c[role]||[];const id=b.dataset.cap;c[role]=c[role].includes(id)?c[role].filter(x=>x!==id):c[role].concat(id);writeStore(CAP_KEY,c);renderArchive()}}
function renderHomeNudges(){const el=$('#homeNudges');if(!el)return;const now=new Date(),today=formatDate(now),items=getTodos(),overdue=items.filter(x=>!x.done&&x.date<today),future=items.filter(x=>!x.done&&x.date>=today).sort((a,b)=>a.date.localeCompare(b.date))[0];let html='';if(overdue.length)html+=`<div class="nudge-card"><b>有 ${overdue.length} 项任务已超过截止日期</b><span>你上周可能经常推迟这类任务，要不要降低难度？</span><button data-nudge="calendar">重新规划</button></div>`;if(future){const days=Math.ceil((parseLocalDate(future.date)-new Date(now.getFullYear(),now.getMonth(),now.getDate()))/86400000);if(days<=2)html+=`<div class="nudge-card"><b>${escapeHtml(future.title)}距离截止还有 ${days===0?'今天':days+' 天'}</b><span>现在先完成一个最小步骤，会更轻松。</span><button data-nudge="calendar">查看任务</button></div>`}else html+=`<div class="nudge-card"><b>今天还想完成一件小事吗？</b><span>你已经有几天没有安排行动，可以从十分钟的小任务重新开始。</span><button data-nudge="calendar">安排一件小事</button></div>`;el.innerHTML=html;el.onclick=e=>{if(e.target.dataset.nudge){openCalendar();showTodoForm()}}}
function openArchive(){ensureArchive();renderArchive();show('archiveScreen')}
function renderArchive(){ensureArchive();const role=$('#targetRoleSelect').value||roleLibrary[0][0];const detail=roleDetails[role]||{};const records=readStore(ARCHIVE_KEY,[]),dirs=readStore(DIRECTION_KEY,[]),caps=readStore(CAP_KEY,{}),done=caps[role]||[],hard=(detail.hard||[]).map((x,i)=>({id:`h${i}`,type:'硬技能',text:x})),soft=(detail.soft||[]).map((x,i)=>({id:`s${i}`,type:'软实力',text:x})),all=hard.concat(soft);writeStore(TARGET_KEY,role);$('#targetRoleIntro').innerHTML=`<h3>${escapeHtml(role)}</h3><p>${escapeHtml(detail.summary||'选择一个岗位，开始积累对应能力证据。')}</p>`;$('#archiveSummary').innerHTML=`<div><b>${records.length}</b><span>成长记录</span></div><div><b>${records.filter(x=>x.category==='技能').length}</b><span>技能</span></div><div><b>${records.filter(x=>x.category==='项目').length}</b><span>项目</span></div><div><b>${dirs.filter(x=>x.decision==='排除方向').length}</b><span>已排除方向</span></div>`;const wi=weekItems(),completed=wi.filter(x=>x.done).length,rate=wi.length?Math.round(completed/wi.length*100):0,over=wi.filter(x=>!x.done&&x.date<formatDate(new Date())).length;$('#weekRange').textContent=`${formatDate(weekStart())} — ${formatDate(new Date(weekStart().getFullYear(),weekStart().getMonth(),weekStart().getDate()+6))}`;$('#weeklySummary').innerHTML=`<div class="review-metrics"><b>${completed}<small>完成</small></b><b>${wi.length}<small>安排</small></b><b>${rate}%<small>完成率</small></b><b>${over}<small>拖延</small></b></div><p>${wi.length?'本周完成率最高的行动，是把计划真正放进日历并按时完成。':'本周还没有日历行动，先安排一个最小步骤吧。'}</p>`;$('#weeklyReflection').value=readStore(REFLECTION_KEY,{})[weekKey()]||'';$('#capabilityProgress').textContent=`${done.length}/${all.length} 已具备` ;$('#capabilityIntro').textContent=`完成一项能力后点击它，系统会把它移动到“已具备”。建议同步在成长记录里留下证据。` ;$('#capabilityList').innerHTML=`<div class="cap-columns"><div><h4>已具备 (${done.length})</h4>${all.filter(x=>done.includes(x.id)).map(x=>`<button class="cap-row done" data-cap="${x.id}"><b>✓</b><span><strong>${escapeHtml(x.text)}</strong><small>${x.type}</small></span></button>`).join('')||'<p class="muted">还没有已完成能力</p>'}</div><div><h4>尚未具备 (${all.length-done.length})</h4>${all.filter(x=>!done.includes(x.id)).map(x=>`<button class="cap-row" data-cap="${x.id}"><b>○</b><span><strong>${escapeHtml(x.text)}</strong><small>${x.type}</small></span></button>`).join('')||'<p class="muted">全部完成，继续积累项目证据</p>'}</div></div><div class="cap-next"><b>建议下一步</b><span>工具：Excel、Power BI或岗位常用系统；项目：完成一份可展示的案例；实习：寻找${escapeHtml(role)}相关岗位。</span></div>`;$('#directionLogList').innerHTML=dirs.length?dirs.slice(0,6).map(x=>`<div class="direction-log"><b>${escapeHtml(x.role)}</b><span class="status-${x.decision==='排除方向'?'out':'in'}">${escapeHtml(x.decision)}</span><small>${escapeHtml(x.reason)}</small></div>`).join(''):'<p class="muted">还没有记录。保留“为什么改变方向”，比只记结果更有价值。</p>';$('#archiveRecordList').innerHTML=records.length?records.slice(0,8).map(x=>`<div class="archive-record"><span>${escapeHtml(x.category)}</span><b>${escapeHtml(x.title)}</b><small>${escapeHtml(x.date)}${x.detail?' · '+escapeHtml(x.detail):''}</small></div>`).join(''):'<p class="muted">还没有成长记录，完成一件小事就可以记下来。</p>'}
const originalOpenHome=openHome;openHome=function(){originalOpenHome();ensureArchive();renderHomeNudges()};
const originalSaveTodos=saveTodos;saveTodos=function(items){originalSaveTodos(items);renderHomeNudges()};
ensureArchive();if(!$('#homeNudges')){const n=document.createElement('div');n.id='homeNudges';n.className='nudge-wrap';$('#homeScreen').appendChild(n)}const savedTarget=localStorage.getItem(TARGET_KEY);if(savedTarget&&[...$('#targetRoleSelect').options].some(x=>x.value===savedTarget))$('#targetRoleSelect').value=savedTarget;renderHomeNudges();

